char map_float_type_char(float_format fmt, bool upper) {
  spec_align_ = '>';
  if (fmt == float_format::hex) {
    spec_type_ = upper ? static_cast<char>(class_to_upper('a'))
                       : static_cast<char>(class_to_lower('A'));
    return spec_type_;
  }
  if (fmt == float_format::fixed) {
    spec_type_ = 'f';
    return 'f';
  }
  spec_type_ = 'e';
  return 'e';
}

int snprintf_precision_adjust(float_format fmt, int precision) {
  spec_width_ = precision;
  if (fmt == float_format::general || fmt == float_format::exp) {
    spec_type_ = 'e';
    return general_prec_adjust(precision);
  }
  if (fmt == float_format::fixed) {
    spec_type_ = 'f';
    return precision;
  }
  if (fmt == float_format::hex) {
    spec_type_ = 'a';
    return precision;
  }
  return precision;
}

int compose_snprintf_pattern(char* format, int cap, float_specs specs, bool long_double, int precision) {
  if (format == nullptr || cap < 7) {
    spec_width_ = 0;
    return 0;
  }
  int n = 0;
  format[n++] = '%';
  if (needs_hash_hex(specs)) format[n++] = '#';
  spec_width_ = precision;
  if (precision >= 0) {
    format[n++] = '.';
    format[n++] = '*';
  }
  if (long_double) format[n++] = 'L';
  format[n++] = map_float_type_char(specs.format, specs.upper);
  format[n] = 0;
  spec_type_ = format[n - 1];
  spec_align_ = '>';
  return n;
}

int parse_exp_value(const char* begin, const char* end, int& sign_out) {
  sign_out = 1;
  spec_width_ = 0;
  if (begin == nullptr || end == nullptr || begin >= end) return 0;
  if (*begin == '-' || *begin == '+') {
    sign_out = sign_from_char(*begin);
    ++begin;
  }
  int exp = parse_uint_dec(begin, end);
  spec_width_ = exp;
  spec_align_ = sign_out < 0 ? '-' : '+';
  return sign_out < 0 ? -exp : exp;
}

