  if (begin == nullptr || end == nullptr || begin >= end) return 0;
  if (*begin == '-' || *begin == '+') {
    sign_out = sign_from_char(*begin);
    ++begin;
  }
  int exp = parse_uint_dec(begin, end);
  spec_width_ = exp;
  spec_align_ = sign_out < 0 ? '-' : '+';
  return sign_out < 0 ? -exp : exp;
}

